      expedited: [[2, "2 days"], [3.5, "2\u20133 days"], [5.5, "3\u20134 days"], [Infinity, "4\u20135 days"]],
      ground: [[2, "3 days"], [3.5, "3\u20134 days"], [5, "4\u20135 days"], [6.5, "5\u20136 days"], [Infinity, "6\u20138 days"]]
